const {chromium} = require('playwright-core');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
(async () => {
  const [base, token, denied, evidence] = process.argv.slice(2);
  const profile = fs.mkdtempSync(path.join(process.env.TMPDIR, 'sheet-'));
  const context = await chromium.launchPersistentContext(profile, {executablePath:process.env.BROWSER_EXECUTABLE, headless:true, args:['--no-sandbox'], viewport:{width:320,height:740}});
  try {
    await context.addCookies([{name:'session',value:token,url:base}]);
    const page=await context.newPage(); page.on('dialog',d=>d.accept());
    await page.goto(base+'/time-entries');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'25h0m0s');
    await page.getByLabel('From date',{exact:true}).fill('2026-03-08');
    await page.getByLabel('To date',{exact:true}).fill('2026-03-08');
    await page.getByLabel('Source',{exact:true}).selectOption('manual');
    await page.getByLabel('Group by',{exact:true}).selectOption('job');
    await page.getByRole('button',{name:'Refresh Timesheets',exact:true}).click();
    await page.waitForURL(url=>url.searchParams.get('date_from')==='2026-03-08');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'23h0m0s');
    assert.equal(await page.locator('[data-time-entry]').count(),1);
    await page.reload();
    assert.equal(await page.locator('[name=date_from]').inputValue(),'2026-03-08');
    assert.equal(await page.locator('[name=source]').inputValue(),'manual');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'23h0m0s');
    await page.getByLabel('Search notes',{exact:true}).fill('no such report match');
    await page.getByLabel('Search notes',{exact:true}).press('Enter');
    await page.waitForURL(url=>url.searchParams.get('search')==='no such report match');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'0s');
    assert.match(await page.locator('#time-entry-list-content').innerText(),/No time entries found matching/);
    await page.getByRole('link',{name:'Clear filters',exact:true}).click();
    await page.waitForURL(url=>url.search==='');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'25h0m0s');
    await page.goto(base+'/time-entries?source=clocked');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'1h0m0s');
    await page.locator('[data-time-entry] a[href$="/edit"]').click();
    await page.locator('[name=notes]').fill('Browser changed report');
    await page.locator('[name=reason]').fill('Browser report review');
    await page.getByRole('button',{name:'Save',exact:true}).click();
    await page.waitForURL(url=>url.pathname==='/time-entries');
    await page.reload();
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'25h0m0s');
    await page.goto(base+'/time-entries?source=clocked');
    await page.getByText('Revision history',{exact:true}).click();
    const text=await page.locator('[data-time-entry]').innerText();
    assert.match(text,/Browser changed report/);assert.match(text,/Browser clocked source row/);assert.match(text,/Browser report review/);
    await page.getByRole('link',{name:'View entry and history',exact:true}).click();
    await page.locator('form[action$="/void"] [name=reason]').fill('Browser report Void');
    await page.getByRole('button',{name:'Void Time Entry',exact:true}).click();
    await page.getByText('Voided — terminal.',{exact:false}).waitFor();
    await page.goto(base+'/time-entries?include_void=true&group_by=job');
    assert.equal(await page.locator('[data-timesheet-total]').innerText(),'24h0m0s');
    assert.match(await page.locator('#time-entry-list-content').innerText(),/Excluded \(Void\)/);
    await page.getByText('Revision history',{exact:true}).click();
    assert.match(await page.locator('#time-entry-list-content').innerText(),/Browser report Void/);
    assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'phone page must contain dense report scrolling');
    await page.screenshot({path:path.join(evidence,'timesheets-phone.png'),fullPage:true});
    await context.clearCookies();await context.addCookies([{name:'session',value:denied,url:base}]);
    const response=await page.goto(base+'/time-entries?include_void=true&group_by=job');
    assert.equal(response.status(),403);
    assert.doesNotMatch(await page.locator('body').innerText(),/Browser exact day row|Browser changed report|Browser report Void/);
    console.log('Persisted phone Timesheets: DST clipping, filter/group/reload/keyboard state, explicit empty result, correction history once, terminal Void excluded, bounded scrolling and denied report passed');
  } finally { await context.close(); }
})().catch(e=>{console.error(e);process.exit(1);});
